create table public.employees (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, outlet_id uuid, employee_code text not null, full_name text not null, email text, phone text, job_title text not null, employment_type text not null default 'permanent' check(employment_type in('permanent','contract','part_time')), joined_on date not null default current_date, status text not null default 'active' check(status in('active','leave','inactive')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,employee_code), unique(organization_id,id), foreign key(organization_id,outlet_id) references public.outlets(organization_id,id)
);
create table public.attendance_records (
 id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete restrict, employee_id uuid not null, outlet_id uuid, attendance_date date not null default current_date, scheduled_start time, scheduled_end time, clock_in timestamptz, clock_out timestamptz, status text not null default 'present' check(status in('present','late','leave','sick','absent')), notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(employee_id,attendance_date), foreign key(organization_id,employee_id) references public.employees(organization_id,id), foreign key(organization_id,outlet_id) references public.outlets(organization_id,id)
);
create index idx_employees_org on public.employees(organization_id,status);create index idx_attendance_org_date on public.attendance_records(organization_id,attendance_date desc);
alter table public.employees enable row level security;alter table public.attendance_records enable row level security;
create policy "members read employees" on public.employees for select to authenticated using((select public.is_organization_member(organization_id)));
create policy "workforce managers manage employees" on public.employees for all to authenticated using((select public.has_organization_role(organization_id,array['owner','admin','hr']))) with check((select public.has_organization_role(organization_id,array['owner','admin','hr'])));
create policy "members read attendance" on public.attendance_records for select to authenticated using((select public.is_organization_member(organization_id)));
create policy "workforce managers manage attendance" on public.attendance_records for all to authenticated using((select public.has_organization_role(organization_id,array['owner','admin','hr']))) with check((select public.has_organization_role(organization_id,array['owner','admin','hr'])));
grant select,insert,update on public.employees,public.attendance_records to authenticated;
create or replace function public.create_employee(employee_code text,employee_name text,employee_job_title text,employee_email text default null,employee_phone text default null,target_outlet_id uuid default null,employee_type text default 'permanent',employee_joined_on date default current_date)
returns jsonb language plpgsql security definer set search_path='' as $$ declare org_id uuid;new_id uuid;begin select organization_id into org_id from public.organization_memberships where user_id=(select auth.uid()) and status='active' limit 1;if org_id is null or not public.has_organization_role(org_id,array['owner','admin','hr']) then raise exception 'permission_denied';end if;if length(trim(employee_code))<2 or length(trim(employee_name))<2 or length(trim(employee_job_title))<2 or employee_type not in('permanent','contract','part_time') then raise exception 'invalid_employee';end if;if target_outlet_id is not null and not exists(select 1 from public.outlets where id=target_outlet_id and organization_id=org_id) then raise exception 'invalid_outlet';end if;insert into public.employees(organization_id,outlet_id,employee_code,full_name,email,phone,job_title,employment_type,joined_on) values(org_id,target_outlet_id,upper(trim(employee_code)),trim(employee_name),nullif(trim(employee_email),''),nullif(trim(employee_phone),''),trim(employee_job_title),employee_type,employee_joined_on) returning id into new_id;return jsonb_build_object('id',new_id);end;$$;
revoke all on function public.create_employee(text,text,text,text,text,uuid,text,date) from public;grant execute on function public.create_employee(text,text,text,text,text,uuid,text,date) to authenticated;
create or replace function public.record_attendance(target_employee_id uuid,event_type text,event_time timestamptz default now()) returns jsonb language plpgsql security definer set search_path='' as $$ declare emp public.employees%rowtype;rec public.attendance_records%rowtype;begin select * into emp from public.employees where id=target_employee_id;if emp.id is null or not public.has_organization_role(emp.organization_id,array['owner','admin','hr']) then raise exception 'permission_denied';end if;select * into rec from public.attendance_records where employee_id=emp.id and attendance_date=(event_time at time zone 'Asia/Jakarta')::date for update;if event_type='clock_in' then if rec.id is not null and rec.clock_in is not null then raise exception 'already_clocked_in';end if;if rec.id is null then insert into public.attendance_records(organization_id,employee_id,outlet_id,attendance_date,clock_in,status,created_by) values(emp.organization_id,emp.id,emp.outlet_id,(event_time at time zone 'Asia/Jakarta')::date,event_time,'present',(select auth.uid())) returning * into rec;else update public.attendance_records set clock_in=event_time,updated_at=now() where id=rec.id returning * into rec;end if;elsif event_type='clock_out' then if rec.id is null or rec.clock_in is null then raise exception 'clock_in_required';end if;if rec.clock_out is not null then raise exception 'already_clocked_out';end if;update public.attendance_records set clock_out=event_time,updated_at=now() where id=rec.id returning * into rec;else raise exception 'invalid_event';end if;return jsonb_build_object('id',rec.id);end;$$;
revoke all on function public.record_attendance(uuid,text,timestamptz) from public;grant execute on function public.record_attendance(uuid,text,timestamptz) to authenticated;
